function collect(s){if(s.found)return;s.found=true;collected++;for(let i=0;i<20;i++)sparks.push({x:s.x,y:s.y,vx:Math.cos(i)*50,vy:Math.sin(i)*50,life:1});updateQuest()}
function cast(){if(time-castAt<.32)return;castAt=time;const target=stones.filter(s=>!s.found).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0];const angle=target?Math.atan2(target.y-player.y,target.x-player.x):-Math.PI/2;shots.push({x:player.x,y:player.y-12,vx:Math.cos(angle)*260,vy:Math.sin(angle)*260,life:3})}
